def _failed(record_id: object, message: object, *, schema_version: str | None = None, **details: object) -> dict:
    payload = {
        "record_id": str(record_id),
        "status": "failed",
        "error_message": str(message),
        **details,
    }
    if schema_version:
        payload["schema_version"] = schema_version
    return payload


